window.LD=window.LD||{};window.LD["party/p8"]={"id":"p8","name":"The Silver Hounds","poss":"The Silver Hounds'","members":["h4","h18","h16"],"leader":"h16","morale":97,"disposition":"wary","motto":"Pockets empty, hearts full.","banner":{"c1":"#e8e8e8","c2":"#7a4cc8","emblem":"paw"},"loc":"sunken_vault","loc_name":"The Sunken Vault","goal":{"text":"to find a relic of the old world","kind":"relic","done":null,"progress":"still looking","missed":true,"crew":"The Silver Hounds","party":"p8"},"vows":[{"text":"to return and finish The Mimic King","day":19,"state":"kept","ended":24,"through":false,"progress":"kept on day 24 of season 1","crew":"The Silver Hounds","party":"p8"},{"text":"never to pay a toll","day":31,"state":"kept","ended":90,"through":true,"progress":"kept on day 30 of season 3","crew":"The Silver Hounds","party":"p8"}],"doing":"last seen delving into The Sunken Vault","progress":null,"today":["Ate 3 rations."],"fights_today":[],"why":null,"founded_day":3,"founded_season":1,"disbanded":null,"anthem":null,"renown":153,"season":{"wins":2,"bosses":0,"floors":8,"gold":0,"deaths":0,"fled":0,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30,"arguments":1},"career":{"wins":23,"bosses":3,"floors":22,"gold":0,"deaths":0,"fled":1,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":88,"arguments":3},"former":["h15"],"fallen":[],"travel":null,"wagon":{"kind":"donkey_cart","name":"Wheelie","label":"donkey cart","seats":2,"haul":28,"comfort":1,"since":22,"desc":"Rattles. Gets there.","moves":true,"puller":{"kind":"donkey","name":"Biscuit","label":"donkey","colour":"grey","owner":null},"paid":[["Tamsin",15],["Isolde",9]]},"pace_gap":7,"rels":[{"party":"p3","score":100},{"party":"p5","score":79},{"party":"p4","score":3},{"party":"p1","score":1}],"events":[{"id":"e112","day":3,"season":1,"sday":3,"kind":"party_formed","imp":4,"text":"Rook and Pickles shake on it over a campfire in the Collapsed Mine: they are now The Silver Hounds. (Honorable, by the look of them.)","heroes":["h15","h4"],"parties":["p8"],"loc":"collapsed_mine"},{"id":"e473","day":15,"season":1,"sday":15,"kind":"boss","imp":5,"text":"Six rounds in, the Silver Hounds kill the Silk Matriarch, a Cave Troll and a Cave Slime at the bottom of the Collapsed Mine. Rook was nearly down when Pickles' Rejuvenate landed. Everyone fought a little better after Rook's Battle Cry. Isolde landed 2 crushing blows, mostly with Pinning Shot. Tamsin landed 2 crushing blows, mostly with Caltrops. An arrow that should have found Tamsin found the strap next to the coin pocket instead. Loot: 4 silver each, 11 chitin, a leg of the Silk Matriarch. Injured: Rook (concussion).","heroes":["h15","h4","h18","h16"],"parties":["p8"],"loc":"collapsed_mine","fight":"f46","foes":["spider_queen","cave_troll","slime"],"where":"at the bottom of The Collapsed Mine","won":true,"close":true,"shape":"close","reworded":-15},{"id":"e477","day":15,"season":1,"sday":15,"kind":"gear","imp":4,"text":"Out of the Collapsed Mine comes Rook, and with Rook comes a pair of gloves spun from something finer than silk from the silk-hung stope: one of a kind, and not yet understood.","heroes":["h15","h4","h18","h16"],"parties":["p8"],"loc":"collapsed_mine"},{"id":"e509","day":15,"season":1,"sday":15,"kind":"goal_done","imp":4,"text":"The Silver Hounds can cross it off: find a relic of the old world. Drinks are on them. Rook found it. XP: Rook +800 (level 10!), Pickles +960 (level 10!), Isolde +800 (level 10!), Tamsin +840 (level 10!).","heroes":["h15","h4","h18","h16"],"parties":["p8"],"xp":{"h15":800,"h4":960,"h18":800,"h16":840}},{"id":"e523","day":15,"season":1,"sday":15,"kind":"big_move","imp":4,"text":"Six rounds in, the Silver Hounds kill the Silk Matriarch, a Cave Troll and a Cave Slime at the bottom of the Collapsed Mine. On the table: Rook +88 renown (7th to 2nd), Tamsin +88 (8th to 3rd), Isolde +88 (6th to 1st) and Pickles +86 (15th to 5th). The Silver Hounds +166 party renown (3rd to 1st among the crews).","heroes":["h15","h16","h18","h4"],"parties":["p8"],"cause":"e473","moves":[{"hero":"h15","gain":88,"from":7,"to":2},{"hero":"h16","gain":88,"from":8,"to":3},{"hero":"h18","gain":88,"from":6,"to":1},{"hero":"h4","gain":86,"from":15,"to":5}],"party_moves":[{"party":"p8","gain":166,"from":3,"to":1}],"fight":"f46"},{"id":"e635","day":19,"season":1,"sday":19,"kind":"rescue","imp":4,"text":"Wren (Emery's hero) owes Rook (Avery's hero) a life now: The Silver Hounds pulled Wren out of trouble in Cragtooth Warren, 2 potions poorer.","heroes":["h15","h20","h4","h18","h16"],"parties":["p8"],"loc":"cragtooth_warren","rescuers":["h15","h4","h18","h16"]},{"id":"e668","day":20,"season":1,"sday":20,"kind":"talent","imp":2,"text":"Tamsin tries out a new verse on the party. Rook suggests a rhyme. It's in the song now.","heroes":["h16","h15"],"parties":["p8"],"loc":"redcrag","skill":"packs_the_house","wx":"rain"},{"id":"e706","day":21,"season":1,"sday":21,"kind":"talent","imp":1,"text":"Tamsin slips a little pepper from their own tin into the Veldrock tavern's soup. The table approves.","heroes":["h16"],"parties":["p8"],"loc":"veldrock","skill":"spice_box"},{"id":"e708","day":21,"season":1,"sday":21,"kind":"ability","imp":2,"text":"Tamsin starts a slow ballad in a rowdy Veldrock tavern and the room goes quiet to listen. Then the encore, then 40 silver, then Isolde carrying the hat home.","heroes":["h16","h18"],"parties":["p8"],"loc":"veldrock","skill":"packs_the_house","sk":"Packs the House","rule":true},{"id":"e722","day":21,"season":1,"sday":21,"kind":"ledger","imp":2,"text":"THE LEDGER: 15 hauls sold this week, 513 silver in all. Biggest haul: Bramble, 86 silver in Thornwall. Back up from the deep: The Silver Hounds (2 days in the Collapsed Mine), The Tidal Ledger (4 days in the Ashveil Crypts), Wren (2 days in Cragtooth Warren).","heroes":["h13","h15","h7","h20"],"parties":["p8","p7"]},{"id":"e737","day":22,"season":1,"sday":22,"kind":"wagon","imp":3,"text":"The Silver Hounds roll out of Veldrock in a donkey cart called Wheelie, 24 silver between them. Who paid: Tamsin 15, Isolde 9.","heroes":["h15","h4","h18","h16"],"parties":["p8"],"loc":"veldrock"},{"id":"e743","day":22,"season":1,"sday":22,"kind":"boss_race","imp":3,"text":"Word in the taverns: The Silver Hounds and Wren are both after The Mimic King. Cragtooth Warren has one way down and room for one winner.","heroes":["h15","h4","h18","h16","h20"],"parties":["p8"],"loc":"cragtooth_warren","wx":"rain"},{"id":"e748","day":22,"season":1,"sday":22,"kind":"gift","imp":2,"text":"Tamsin admired Isolde's Kobold Whistle one too many times. Now it's Tamsin's.","heroes":["h18","h16"],"parties":["p8"],"loc":"redcrag","wx":"rain"},{"id":"e759","day":22,"season":1,"sday":22,"kind":"campfire","imp":1,"text":"Rook carries Tamsin's pack for the last mile without being asked.","heroes":["h15","h16"],"parties":["p8"],"loc":"redcrag","wx":"rain"},{"id":"e767","day":23,"season":1,"sday":23,"kind":"party_life","imp":1,"text":"Isolde rides ahead, rides back, rides ahead again. Tamsin is not amused.","heroes":["h15","h4","h18","h16"],"parties":["p8"],"loc":"redcrag","wx":"fog"},{"id":"e782","day":23,"season":1,"sday":23,"kind":"meet","imp":1,"text":"The Silver Hounds and Wren share a fire in Cragtooth Warren. There is a short argument about the best road to Ironhaven.","heroes":["h15","h4","h18","h16","h20"],"parties":["p8"],"loc":"cragtooth_warren","wx":"fog"},{"id":"e793","day":24,"season":1,"sday":24,"kind":"delve","imp":1,"text":"The Silver Hounds descend into Cragtooth Warren, mostly explored (65%).","heroes":["h15","h4","h18","h16"],"parties":["p8"],"loc":"cragtooth_warren","wx":"fog"},{"id":"e796","day":24,"season":1,"sday":24,"kind":"boss","imp":5,"text":"Isolde hits hardest while the Silver Hounds finish off 2 Cave Trolls and the Mimic King at the bottom of Cragtooth Warren, though Rook went down. It was Isolde's Follow My Arrow that dropped the cave troll. Rook's Hired Help brought help, and the help earned its keep. Pickles saved Ice Wall for when it mattered. Tamsin's Marching Song turned the fight. Loot: 50 silver each, 2 gems, 8 trinkets.","heroes":["h15","h4","h18","h16"],"parties":["p8"],"loc":"cragtooth_warren","fight":"f71","foes":["mimic_king","cave_troll","cave_troll"],"where":"at the bottom of Cragtooth Warren","won":true,"close":true,"shape":"hero","reworded":-32,"wx":"fog"},{"id":"e797","day":24,"season":1,"sday":24,"kind":"vow_kept","imp":5,"text":"VOW KEPT. The Silver Hounds came back, as sworn on day 19 of season 1, and finished it: The Mimic King is dead.","heroes":["h15","h4","h18","h16"],"parties":["p8"],"cause":"e616","in_fight":"f71"},{"id":"e798","day":24,"season":1,"sday":24,"kind":"treasure","imp":2,"text":"The hoard The Mimic King died defending comes to 9 gold pieces and 2 silver. It leaves in every pocket available.","heroes":["h15","h4","h18","h16"],"parties":["p8"],"loc":"cragtooth_warren","in_fight":"f71","wx":"fog"},{"id":"e799","day":24,"season":1,"sday":24,"kind":"sniped","imp":3,"text":"Deep in Cragtooth Warren, Wren hears the roaring below stop. The Silver Hounds have reached The Mimic King first. Wren stays and works the floors that are left.","heroes":["h20","h15","h4","h18","h16"],"parties":["p8"],"loc":"cragtooth_warren","snipers":["h15","h4","h18","h16"],"where":"inside","boss":"The Mimic King","in_fight":"f71","wx":"fog"},{"id":"e800","day":24,"season":1,"sday":24,"kind":"race_won","imp":1,"text":"The Silver Hounds win the race to The Mimic King, ahead of Wren. The bets are paid out in Ironhaven before the blood is dry.","heroes":["h15","h4","h18","h16"],"parties":["p8"],"loc":"cragtooth_warren","in_fight":"f71","wx":"fog"},{"id":"e801","day":24,"season":1,"sday":24,"kind":"gear","imp":4,"text":"A ring that feels faintly damp from the hoard hall leaves the dark of Cragtooth Warren in Rook's pack. There isn't another. What it can do is anyone's guess until a town names it.","heroes":["h15","h4","h18","h16"],"parties":["p8"],"loc":"cragtooth_warren","wx":"fog"},{"id":"e802","day":24,"season":1,"sday":24,"kind":"delve_day","imp":1,"text":"The Silver Hounds work floor 2 of Cragtooth Warren at a steady pace: 1 room (the hoard hall).","heroes":["h15","h4","h18","h16"],"parties":["p8"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":1,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["unique"],"fears":0,"wild":[]},"wx":"fog"},{"id":"e803","day":24,"season":1,"sday":24,"kind":"delve_done","imp":1,"text":"The Silver Hounds climb the last ladder after a day, and the sitting down happens at the top of it. They turned up the hoard hall, reached the deepest floor, worked through 1 room and came away with 384 silver between them.","heroes":["h15","h4","h18","h16"],"parties":["p8"],"loc":"cragtooth_warren","days":1,"bottom":true,"rooms":["the hoard hall"],"gold":384,"turn":"done","wx":"fog"},{"id":"e833","day":24,"season":1,"sday":24,"kind":"big_move","imp":4,"text":"Isolde hits hardest while the Silver Hounds finish off 2 Cave Trolls and the Mimic King at the bottom of Cragtooth Warren, though Rook went down. On the table: Isolde +108 renown (holds 1st), Rook +104 (4th to 3rd), Tamsin +104 (3rd to 2nd) and Pickles +104 (6th to 4th). The Silver Hounds +198 party renown (holds 1st among the crews).","heroes":["h18","h15","h16","h4"],"parties":["p8"],"cause":"e796","moves":[{"hero":"h18","gain":108,"from":1,"to":1},{"hero":"h15","gain":104,"from":4,"to":3},{"hero":"h16","gain":104,"from":3,"to":2},{"hero":"h4","gain":104,"from":6,"to":4}],"party_moves":[{"party":"p8","gain":198,"from":1,"to":1}],"fight":"f71"},{"id":"e854","day":25,"season":1,"sday":25,"kind":"party_life","imp":1,"text":"Tamsin spends the whole road in the dust Isolde kicks up, and says so.","heroes":["h15","h4","h18","h16"],"parties":["p8"],"loc":"cragtooth_warren","wx":"fog"},{"id":"e855","day":25,"season":1,"sday":25,"kind":"talent","imp":1,"text":"Isolde blazes the trees round camp so the next crew through can find the water. Good manners on the road.","heroes":["h18"],"parties":["p8"],"loc":"redcrag","skill":"trailblazer","wx":"fog"},{"id":"e868","day":25,"season":1,"sday":25,"kind":"meet","imp":1,"text":"The Silver Hounds and The Thunder of Frosthold share a fire in Redcrag Hills. Isolde shares a bad map.","heroes":["h15","h4","h18","h16","h5","h3","h2","h11"],"parties":["p8","p3"],"loc":"redcrag","wx":"fog"},{"id":"e870","day":25,"season":1,"sday":25,"kind":"talent","imp":2,"text":"Pickles finds the rarest herb in the valley growing in her own footprint. Heart of the Wild, the guild calls it.","heroes":["h4"],"parties":["p8"],"loc":"redcrag","skill":"heart_of_the_wild","wx":"fog"},{"id":"e877","day":25,"season":1,"sday":25,"kind":"argument","imp":2,"text":"Rook says one thing too many about who ate the last of the cheese. Pickles says two.","heroes":["h15","h4"],"parties":["p8"]},{"id":"e893","day":26,"season":1,"sday":26,"kind":"party_life","imp":1,"text":"Tamsin asks Isolde if the view is nice up there. It is.","heroes":["h15","h4","h18","h16"],"parties":["p8"],"loc":"redcrag"},{"id":"e920","day":26,"season":1,"sday":26,"kind":"ability","imp":2,"text":"A Veldrock landlord books Tamsin for one song and gets nine. 59 silver, a free supper, and a queue of people wanting the words written down.","heroes":["h16"],"parties":["p8"],"loc":"veldrock","skill":"packs_the_house","sk":"Packs the House","rule":true},{"id":"e938","day":27,"season":1,"sday":27,"kind":"party_life","imp":3,"text":"Tamsin arrives at camp an hour behind Isolde and finds the good spot by the fire taken.","heroes":["h15","h4","h18","h16"],"parties":["p8"],"loc":"veldrock"},{"id":"e966","day":27,"season":1,"sday":27,"kind":"party_strain","imp":3,"text":"Rook is still limping, and has started asking The Silver Hounds whose idea the last dungeon was.","heroes":["h15"],"parties":["p8"],"loc":"frosthold"},{"id":"e982","day":28,"season":1,"sday":28,"kind":"night","imp":3,"text":"Rook's ghost story in Whitepeak Pass ends with \"...and it was standing right behind them.\" Tamsin does not look behind them once, all night.","heroes":["h15","h4","h18","h16"],"parties":["p8"],"loc":"whitepeak"},{"id":"e997","day":28,"season":1,"sday":28,"kind":"boss_race","imp":3,"text":"Somebody chalks a tally on the board for the race to Hrimnir, Who Walks Under Snow: The Thunder of Frosthold and The Silver Hounds. Odds are offered, mostly on whoever's buying.","heroes":["h5","h3","h2","h11","h15","h4","h18","h16"],"parties":["p3","p8"],"loc":"frostspire"},{"id":"e1007","day":28,"season":1,"sday":28,"kind":"talent","imp":2,"text":"Pickles brews something green and bitter for Rook's cough. Rook hates it. The cough's gone by morning. (Herbalism, if anyone's asking.)","heroes":["h4","h15"],"parties":["p8"],"loc":"whitepeak","skill":"herbalism"},{"id":"e1010","day":28,"season":1,"sday":28,"kind":"ledger","imp":2,"text":"Counters and coin this week: 23 sales, 2,254 silver changing hands. Biggest haul: Tobias, 303 silver in Carrbridge. Back up from the deep: The Scarlet Thorns (2 days in Thornmere Ruins), The Tidal Ledger (2 days in the Ashveil Crypts), The Silver Hounds (1 day in Cragtooth Warren).","heroes":["h6","h7","h15"],"parties":["p1","p7","p8"]},{"id":"e1017","day":29,"season":1,"sday":29,"kind":"party_life","imp":1,"text":"Rook asks, for the fourth time this week, whether the donkey cart has ever heard of springs.","heroes":["h15"],"parties":["p8"],"loc":"whitepeak"},{"id":"e1035","day":29,"season":1,"sday":29,"kind":"talent","imp":1,"text":"Rook says 'hold' and the whole party holds, perfectly, while the floor collapses in front of them.","heroes":["h15"],"parties":["p8"],"loc":"frostspire","skill":"warlords_command"},{"id":"e1041","day":29,"season":1,"sday":29,"kind":"campfire","imp":1,"text":"Isolde shows Rook a scar and Rook shows one back. They compare, warily.","heroes":["h18","h15"],"parties":["p8"],"loc":"frostspire"},{"id":"e1050","day":30,"season":1,"sday":30,"kind":"delve","imp":1,"text":"The Silver Hounds descend into Frostspire, untouched (0%).","heroes":["h15","h4","h18","h16"],"parties":["p8"],"loc":"frostspire"},{"id":"e1051","day":30,"season":1,"sday":30,"kind":"trap","imp":2,"text":"Rook springs an ice slide in the sentry stair on floor 1 of Frostspire (bruised ribs).","heroes":["h15"],"parties":["p8"],"loc":"frostspire"},{"id":"e1052","day":30,"season":1,"sday":30,"kind":"delve_day","imp":1,"text":"The Silver Hounds work floor 1 of Frostspire at a steady pace: 4 rooms (the wind-scoured foot, a hidden room behind the wind-scoured foot, the hunters' shrine and 1 more).","heroes":["h15","h4","h18","h16"],"parties":["p8"],"loc":"frostspire","pace":"steady","stats":{"rooms":4,"size":4,"floor":1,"traps":1,"sprung":1,"trap_inj":1,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":2,"wild":[]}},{"id":"e1070","day":30,"season":1,"sday":30,"kind":"party_leave","imp":3,"text":"Rook leaves The Silver Hounds: says this party is going to get someone killed, and isn't waiting to find out who.","heroes":["h15","h4","h18","h16"],"parties":["p8"],"loc":"frostspire"},{"id":"e1075","day":30,"season":1,"sday":30,"kind":"delve_done","imp":1,"text":"After a day underground, The Silver Hounds climb back into the open air, gulping it down like water. They made it to floor 1, cleared 4 rooms, turned up a hidden room behind the wind-scoured foot and split 12 silver on the way up.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"frostspire","days":1,"bottom":false,"rooms":["a hidden room behind the wind-scoured foot"],"gold":12},{"id":"e1082","day":30,"season":1,"sday":30,"kind":"season_end","imp":5,"text":"Season 1 ends. Gorm is Hero of the Season with 429 renown. The Silver Hounds finish as the top party.","heroes":["h9","h4","h18","h16"],"parties":["p8"]},{"id":"e1083","day":30,"season":1,"sday":30,"kind":"top_party","imp":4,"text":"TOP PARTY: The Silver Hounds (Pickles, Isolde and Tamsin) end season 1 as the league's best crew, 545 party renown. Their season: 2 bosses, 10 fights won and 9 floors explored.","heroes":["h4","h18","h16"],"parties":["p8"]},{"id":"e1128","day":31,"season":2,"sday":1,"kind":"journey","imp":2,"text":"On the way to Carrbridge, The Green Arrows catch up with The Silver Hounds. The conversation turns to the best way to cook a rat and never recovers.","heroes":["h17","h13","h14","h4","h18","h16"],"parties":["p5","p8"]},{"id":"e1129","day":31,"season":2,"sday":1,"kind":"ability","imp":2,"text":"Tamsin plays a Carrbridge tavern so packed the landlord opens the windows so the street can hear. 25 silver, a lot of new fans and a very happy party.","heroes":["h16"],"parties":["p8"],"loc":"carrbridge","skill":"packs_the_house","sk":"Packs the House","rule":true,"wx":"storm"},{"id":"e1152","day":31,"season":2,"sday":1,"kind":"vow","imp":3,"text":"The Silver Hounds stand before the league and swear it: never to pay a toll. The Annals are watching.","heroes":["h4","h18","h16"],"parties":["p8"]},{"id":"e1211","day":34,"season":2,"sday":4,"kind":"delve","imp":1,"text":"The Silver Hounds descend into the Ashveil Crypts, untouched (0%).","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e1212","day":34,"season":2,"sday":4,"kind":"fight","imp":2,"text":"The Silver Hounds, in fine spirits lately, make short work of 4 Giant Rats in the gravediggers' shed on floor 1 of the Ashveil Crypts. Isolde landed Patient Shot on the giant rat hard enough to hear from the back. Marching Song did more for this fight than the scoreboard shows. That was Isolde. Loot: 2 rat haunches, 1 fang. Isolde, who has been afraid of the dead since childhood, does not run. Nobody says anything. Everybody noticed.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"ashveil_crypts","fight":"f92","foes":["giant_rat","giant_rat","giant_rat"],"where":"in the gravediggers' shed on floor 1 of the Ashveil Crypts","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"rain"},{"id":"e1213","day":34,"season":2,"sday":4,"kind":"delve_day","imp":1,"text":"The Silver Hounds work floor 1 of the Ashveil Crypts at a steady pace: 4 rooms (the lych-gate, the gatekeeper's lodge, the gravediggers' shed and 1 more).","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":4,"size":3,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":[]},"wx":"rain"},{"id":"e1228","day":34,"season":2,"sday":4,"kind":"campfire","imp":1,"text":"Pickles and Isolde have shared a month of roads in The Silver Hounds. Ask either one about the other and settle in for a story.","heroes":["h4","h18"],"parties":["p8"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e1237","day":35,"season":2,"sday":5,"kind":"fight","imp":1,"text":"Two Giant Rats and a Skeleton fall to the Silver Hounds in the gatehouse on floor 1 of the Ashveil Crypts. Isolde's Pinning Shot took most of the fight out of the skeleton in one go. Ask the others what won it: Tamsin's Marching Song. Loot: 1 fang, a rat haunch, 4 bones.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"ashveil_crypts","fight":"f93","foes":["giant_rat","giant_rat","skeleton"],"where":"in the gatehouse on floor 1 of the Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-5,"wx":"storm"},{"id":"e1238","day":35,"season":2,"sday":5,"kind":"fight","imp":1,"text":"With Isolde hitting hardest, the Silver Hounds defeat 3 Skeletons in the skeletons' quiet corner on floor 1 of the Ashveil Crypts. The skeleton took Isolde's Patient Shot full on and was never the same after. Loot: 11 bones, 2 crypt-caps.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"ashveil_crypts","fight":"f94","foes":["skeleton","skeleton","skeleton"],"where":"in the skeletons' quiet corner on floor 1 of the Ashveil Crypts","won":true,"close":false,"shape":"hero","reworded":-29,"wx":"storm"},{"id":"e1239","day":35,"season":2,"sday":5,"kind":"fight","imp":2,"text":"In the choir loft on floor 1 of the Ashveil Crypts, 2 Skeletons and 2 Skeleton Archers get in the Silver Hounds' way, briefly. It was even until Isolde's Patient Shot. Then it wasn't. Ask the others what won it: Isolde's Marching Song. Loot: 15 bones, 2 crypt-caps.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"ashveil_crypts","fight":"f95","foes":["skeleton","skeleton","skeleton_archer"],"where":"in the choir loft on floor 1 of the Ashveil Crypts","won":true,"close":false,"shape":"place","reworded":-13,"wx":"storm"},{"id":"e1240","day":35,"season":2,"sday":5,"kind":"delve_day","imp":1,"text":"The Silver Hounds work floor 1 of the Ashveil Crypts at a push pace: 5 rooms (the gatehouse, the skeletons' quiet corner, the chapel of statues and 2 more).","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"ashveil_crypts","pace":"push","stats":{"rooms":5,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":3,"close":0,"gear":[],"fears":5,"wild":[]},"wx":"storm"},{"id":"e1241","day":35,"season":2,"sday":5,"kind":"night","imp":2,"text":"Something small and clever gets into The Silver Hounds' camp on floor 1 of the Ashveil Crypts overnight. Tamsin wakes up 9 silver and 3 rations lighter.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e1267","day":35,"season":2,"sday":5,"kind":"campfire","imp":1,"text":"A month in The Silver Hounds: Pickles could pick Tamsin's footsteps out of a crowd now.","heroes":["h4","h16"],"parties":["p8"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e1268","day":35,"season":2,"sday":5,"kind":"campfire","imp":1,"text":"Isolde and Tamsin see in a month of The Silver Hounds by splitting the last good bottle. Nobody else is offered any.","heroes":["h18","h16"],"parties":["p8"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e1288","day":36,"season":2,"sday":6,"kind":"delve_day","imp":1,"text":"The Silver Hounds work floor 1 of the Ashveil Crypts at a push pace: 4 rooms (the lantern-stone, the cold room, the sexton's lodging and 1 more).","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"ashveil_crypts","pace":"push","stats":{"rooms":4,"size":3,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":2,"wild":[]},"wx":"storm"},{"id":"e1289","day":36,"season":2,"sday":6,"kind":"talent","imp":1,"text":"Isolde warms the crew's socks with a snap of the fingers. Nothing has ever been more appreciated.","heroes":["h18"],"parties":["p8"],"loc":"ashveil_crypts","skill":"cantrips","wx":"storm"},{"id":"e1311","day":37,"season":2,"sday":7,"kind":"delve_day","imp":1,"text":"The Silver Hounds work floor 1 of the Ashveil Crypts at a cautious pace: 3 rooms (the reliquary passage, the chantry, the grave-goods store).","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"ashveil_crypts","pace":"cautious","stats":{"rooms":3,"size":3,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"storm"},{"id":"e1329","day":37,"season":2,"sday":7,"kind":"talent","imp":2,"text":"Pickles finds moonpetal growing in a crack at the Ashveil Crypts, glowing faintly. It's worth more than the fight was. Every druid learns Herbalism sooner or later. Not every druid learns it like that.","heroes":["h4"],"parties":["p8"],"loc":"ashveil_crypts","skill":"herbalism","wx":"storm"},{"id":"e1347","day":38,"season":2,"sday":8,"kind":"fight","imp":1,"text":"Win number six in a row: the Silver Hounds dispatch Risen Dead, a Skeleton Archer and a Skeleton in the funeral feast hall on floor 2 of the Ashveil Crypts. The final blow was Tamsin's Pounce. Pickles fought like someone with somewhere better to be afterwards. Loot: 2 grave dust, 2 remains, 9 bones.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"ashveil_crypts","fight":"f111","foes":["zombie","skeleton_archer","skeleton"],"where":"in the funeral feast hall on floor 2 of the Ashveil Crypts","won":true,"close":false,"shape":"streak","reworded":-25,"wx":"storm"},{"id":"e1348","day":38,"season":2,"sday":8,"kind":"famous_trap","imp":3,"text":"The Ninth Step claims Isolde in the Ashveil Crypts, the first it has caught since the new tenant moved in.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e1349","day":38,"season":2,"sday":8,"kind":"delve_day","imp":1,"text":"The Silver Hounds work floor 2 of the Ashveil Crypts at a steady pace: 4 rooms (the grave-goods store, the funeral feast hall, The Ninth Step and 1 more).","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":4,"size":3,"floor":2,"traps":1,"sprung":1,"trap_inj":1,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common","common"],"fears":2,"wild":[]},"wx":"storm"},{"id":"e1366","day":38,"season":2,"sday":8,"kind":"campfire","imp":2,"text":"A wagon gets stuck on the road. Isolde and Tamsin push it out together and refuse the farmer's coin.","heroes":["h18","h16"],"parties":["p8"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e1383","day":39,"season":2,"sday":9,"kind":"party_life","imp":3,"text":"Isolde called a halt on floor 2 by the simple method of sitting on it. A short debate followed, and The Silver Hounds turn for the stairs with Isolde first up the steps, very briskly.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"ashveil_crypts","refusal":"h18","wx":"storm"},{"id":"e1384","day":39,"season":2,"sday":9,"kind":"delve_done","imp":3,"text":"The daylight is a shock after 6 days, and The Silver Hounds come out into it shading every eye. They disarmed 1 trap, got down to floor 2, inked 39% of the map, turned up the gatekeeper's lodge, the chapel of statues, the chantry and 3 more good rooms, cleared 20 rooms, split 62 silver on the way up and turned back when one of them would go no further. The Ashveil Crypts is mostly unexplored (31%), going by everyone's notes.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"ashveil_crypts","days":6,"bottom":false,"rooms":["the gatekeeper's lodge","the chapel of statues"],"gold":62,"turn":"refused","wx":"storm"},{"id":"e1423","day":40,"season":2,"sday":10,"kind":"ability","imp":2,"text":"Word gets round Ashfen that Tamsin is playing tonight. They're standing on the tables by nine. 40 silver in tips, and Pickles gets free drinks for being with the band.","heroes":["h16","h4"],"parties":["p8"],"loc":"ashfen","skill":"packs_the_house","sk":"Packs the House","rule":true,"wx":"storm"},{"id":"e1429","day":40,"season":2,"sday":10,"kind":"campfire","imp":1,"text":"Pickles fixes the squeak in Tamsin's lantern with a tiny screwdriver and a smug look.","heroes":["h4","h16"],"parties":["p8"],"loc":"ashfen","wx":"storm"},{"id":"e1458","day":41,"season":2,"sday":11,"kind":"bond","imp":3,"text":"The Silver Hounds and The Tidal Ledger are rivals now, starting with Pickles and Vex.","heroes":["h4","h7"],"parties":["p8","p7"],"bond":"rivals"},{"id":"e1479","day":41,"season":2,"sday":11,"kind":"goal","imp":1,"text":"After a long night's talk, The Silver Hounds settle on a goal: to finish the season as one of the top three parties.","heroes":["h4","h18","h16"],"parties":["p8"]},{"id":"e1541","day":43,"season":2,"sday":13,"kind":"talent","imp":2,"text":"Isolde explains every ruin along the road to Tamsin. Three of the explanations are probably true. That's Local History for you.","heroes":["h18","h16"],"parties":["p8"],"loc":"redcrag","skill":"local_history","wx":"fog"},{"id":"e1563","day":44,"season":2,"sday":14,"kind":"fight","imp":2,"text":"The Silver Hounds, in fine spirits lately, see off 2 Giant Bats and 2 Kobolds in Redcrag Hills. Somewhere around Pickles' Thorn Whip, the other side stopped believing. Loot: 3 silver each, 3 ore, a kobold firepepper.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"redcrag","fight":"f116","foes":["giant_bat","kobold","kobold"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e1607","day":45,"season":2,"sday":15,"kind":"campfire","imp":3,"text":"Tamsin brings back a brace of rabbits for the pot. Isolde cooks them. Teamwork.","heroes":["h16","h18"],"parties":["p8"],"loc":"redcrag","wx":"fog"},{"id":"e1633","day":46,"season":2,"sday":16,"kind":"ability","imp":2,"text":"Tamsin plays a wet Tuesday at a Veldrock tavern to six people and a dog. By the last song there are sixty, and the dog is howling along. 37 silver in the hat.","heroes":["h16"],"parties":["p8"],"loc":"veldrock","skill":"packs_the_house","sk":"Packs the House","rule":true,"wx":"snow"},{"id":"e1635","day":46,"season":2,"sday":16,"kind":"talent","imp":1,"text":"Isolde shoes a horse for a Veldrock farrier who has had too much ale to do it. The farrier pays in silver and gratitude.","heroes":["h18"],"parties":["p8"],"loc":"veldrock","skill":"farrier","wx":"snow"},{"id":"e1667","day":47,"season":2,"sday":17,"kind":"boss_race","imp":3,"text":"Mother Thornmere has visitors coming. The Scarlet Thorns and The Silver Hounds are both on the way to Thornmere Ruins, and nobody is waiting for the others.","heroes":["h6","h9","h4","h18","h16"],"parties":["p1","p8"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1698","day":48,"season":2,"sday":18,"kind":"talent","imp":2,"text":"Tamsin plays two encores at the Carrbridge tavern and the landlord pays him to stop so the place can close. That's Packs the House for you.","heroes":["h16"],"parties":["p8"],"loc":"carrbridge","skill":"packs_the_house"},{"id":"e1709","day":48,"season":2,"sday":18,"kind":"argument","imp":1,"text":"Isolde and Pickles of The Silver Hounds have a shouting match about the ethics of looting bodies.","heroes":["h18","h4"],"parties":["p8"]},{"id":"e1718","day":49,"season":2,"sday":19,"kind":"road","imp":1,"text":"A pilgrim tells The Silver Hounds the world is ending. Isolde asks when.","heroes":["h4","h18","h16"],"parties":["p8"]},{"id":"e1730","day":49,"season":2,"sday":19,"kind":"talent","imp":1,"text":"Brambles draw back from the path as Pickles walks through. Somebody asks how. 'Heart of the Wild,' says Pickles.","heroes":["h4"],"parties":["p8"],"loc":"bleakmarsh","skill":"heart_of_the_wild","wx":"fog"},{"id":"e1741","day":50,"season":2,"sday":20,"kind":"party_life","imp":1,"text":"Tamsin arrives in the Wheelie with straw in their hair and a face like thunder.","heroes":["h16"],"parties":["p8"],"loc":"bleakmarsh","wx":"fog"},{"id":"e1766","day":50,"season":2,"sday":20,"kind":"campfire","imp":1,"text":"Isolde and Pickles find a pear tree by the road and eat far more than is wise.","heroes":["h18","h4"],"parties":["p8"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1789","day":51,"season":2,"sday":21,"kind":"delve","imp":1,"text":"The Silver Hounds descend into Thornmere Ruins, mostly explored (74%).","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1823","day":52,"season":2,"sday":22,"kind":"delve_day","imp":1,"text":"The Silver Hounds work floor 3 of Thornmere Ruins at a cautious pace: 3 rooms (the ossuary, the lantern rack, the gallery of charms).","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":3,"size":3,"floor":3,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"fog"},{"id":"e1824","day":52,"season":2,"sday":22,"kind":"night","imp":1,"text":"Something small and clever gets into The Silver Hounds' camp on floor 3 of Thornmere Ruins overnight. Isolde wakes up 7 silver and 2 rations lighter.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1851","day":53,"season":2,"sday":23,"kind":"fight","imp":2,"text":"In the reed stair on floor 3 of Thornmere Ruins, 3 Swamp Trolls, a Will-o'-Wisp and a Siren get in the Silver Hounds' way, briefly. Somewhere around Pickles' Nature's Wrath, the other side stopped believing. Tamsin kept them off everyone with Marching Song. Loot: 28 silver each, 7 herbs, 4 troll haunches.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"thornmere_ruins","fight":"f130","foes":["swamp_troll","swamp_troll","swamp_troll"],"where":"in the reed stair on floor 3 of Thornmere Ruins","won":true,"close":false,"shape":"place","reworded":-3,"wx":"fog"},{"id":"e1854","day":53,"season":2,"sday":23,"kind":"boss","imp":5,"text":"The Silver Hounds finish off Mother Thornmere, a Swamp Troll and a Siren at the bottom of Thornmere Ruins and live to tell of it. Isolde picked out the siren and finished the job with Patient Shot. Pickles loosed Thorn Whip, and it dropped. Pickles's Ice Wall turned the fight. Tamsin landed 2 crushing blows, mostly with Pounce. Loot: 258 silver each, 18 moonpetal, 11 bottled wisplight.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"thornmere_ruins","fight":"f131","foes":["hag_mother","swamp_troll","siren"],"where":"at the bottom of Thornmere Ruins","won":true,"close":true,"shape":"plain","reworded":-15,"wx":"fog"},{"id":"e1855","day":53,"season":2,"sday":23,"kind":"treasure","imp":2,"text":"Under the bedding of Mother Thornmere, rank and lumpy, lies 15 gold pieces and 2 silver.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"thornmere_ruins","in_fight":"f131","wx":"fog"},{"id":"e1856","day":53,"season":2,"sday":23,"kind":"sniped","imp":3,"text":"Deep in Thornmere Ruins, The Tidal Ledger hears the roaring below stop. The Silver Hounds have reached Mother Thornmere first. The Tidal Ledger stays and works the floors that are left.","heroes":["h7","h19","h4","h18","h16"],"parties":["p7","p8"],"loc":"thornmere_ruins","snipers":["h4","h18","h16"],"where":"inside","boss":"Mother Thornmere","in_fight":"f131","wx":"fog"},{"id":"e1857","day":53,"season":2,"sday":23,"kind":"race_won","imp":1,"text":"The Silver Hounds win the race to Mother Thornmere, ahead of The Tidal Ledger. The bets are paid out in Carrbridge before the blood is dry.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"thornmere_ruins","in_fight":"f131","wx":"fog"},{"id":"e1858","day":53,"season":2,"sday":23,"kind":"gear","imp":4,"text":"Isolde carries a knot of hair and reed on a cord from the Hag Mother's nest up out of Thornmere Ruins wrapped in a cloak. It hums. Someone in town will have to say why.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1859","day":53,"season":2,"sday":23,"kind":"delve_day","imp":1,"text":"The Silver Hounds work floor 3 of Thornmere Ruins at a steady pace: 3 rooms (the confession box, the reed stair, the Hag Mother's nest).","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":3,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":["cosmetic","unique"],"fears":0,"wild":[]},"wx":"fog"},{"id":"e1860","day":53,"season":2,"sday":23,"kind":"delve_done","imp":3,"text":"Up the last steps after 3 days: The Silver Hounds climb into the sun and nobody says anything for a while. They reached the deepest floor, took the teeth out of 1 trap, cleared 6 rooms, turned up the ossuary, the lantern rack, the confession box and 1 more good room, mapped 9% of it and split 1227 silver on the way up. Thornmere Ruins is mostly explored (83%), going by everyone's notes.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"thornmere_ruins","days":3,"bottom":true,"rooms":["the ossuary","the lantern rack"],"gold":1227,"turn":"done","wx":"fog"},{"id":"e1864","day":53,"season":2,"sday":23,"kind":"meet","imp":2,"text":"The Tidal Ledger and The Silver Hounds end up at the same fire in Thornmere Ruins. Nobody speaks. Everybody keeps a hand near a weapon.","heroes":["h7","h19","h4","h18","h16"],"parties":["p7","p8"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1876","day":53,"season":2,"sday":23,"kind":"big_move","imp":4,"text":"The Silver Hounds finish off Mother Thornmere, a Swamp Troll and a Siren at the bottom of Thornmere Ruins and live to tell of it. On the table: Isolde +140 renown (10th to 1st), Pickles +136 (17th to 3rd) and Tamsin +131 (13th to 2nd). The Silver Hounds +210 party renown (5th to 1st among the crews).","heroes":["h18","h4","h16"],"parties":["p8"],"cause":"e1854","moves":[{"hero":"h18","gain":140,"from":10,"to":1},{"hero":"h4","gain":136,"from":17,"to":3},{"hero":"h16","gain":131,"from":13,"to":2}],"party_moves":[{"party":"p8","gain":210,"from":5,"to":1}],"fight":"f131"},{"id":"e1936","day":55,"season":2,"sday":25,"kind":"talent","imp":2,"text":"Tamsin plays a new song at the Carrbridge tavern about Pickles. Pickles goes red and orders more ale. Somebody asks how. 'Songwriter,' says Tamsin.","heroes":["h16","h4"],"parties":["p8"],"loc":"carrbridge","skill":"songwriter"},{"id":"e1941","day":55,"season":2,"sday":25,"kind":"ability","imp":2,"text":"The Carrbridge tavern is full before Tamsin has tuned up, and nobody leaves before the third encore. 57 silver in the hat, and the crew sings along from the front table.","heroes":["h16"],"parties":["p8"],"loc":"carrbridge","skill":"packs_the_house","sk":"Packs the House","rule":true},{"id":"e1952","day":56,"season":2,"sday":26,"kind":"raid","imp":5,"text":"Carrbridge is attacked at dusk by will-o'-wisps out of Thornmere Ruins, and Pickles, Tamsin and Isolde hold the gate. The town pays the defenders 25 silver each, and nobody in Carrbridge will buy their own drink tonight.","heroes":["h4","h16","h18"],"parties":["p8"],"loc":"carrbridge","fight":"f137"},{"id":"e1953","day":56,"season":2,"sday":26,"kind":"song","imp":3,"text":"New at The Honest Toll tonight: \"The Gate at Carrbridge\". The bard swears every word is true.","heroes":["h4","h16","h18"],"parties":["p8"],"loc":"carrbridge","song":"s56_14"},{"id":"e1960","day":56,"season":2,"sday":26,"kind":"ambush","imp":2,"text":"Isolde hits hardest as the Silver Hounds cut down 3 Wolves on the road to Ironhaven. Two wolves went down together, and they have Tamsin's Headshot to thank. Ask the others what won it: Isolde's Marching Song. Loot: 3 pelts, 3 fangs & claws, 3 wolf haunches.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"kingsroad","fight":"f138","foes":["wolf","wolf","wolf"],"where":"on the road to Ironhaven","won":true,"close":false,"shape":"hero","reworded":-23},{"id":"e2011","day":57,"season":2,"sday":27,"kind":"road","imp":1,"text":"A pilgrim tells The Silver Hounds the world is ending. Tamsin asks when.","heroes":["h4","h18","h16"],"parties":["p8"]},{"id":"e2012","day":57,"season":2,"sday":27,"kind":"ambush","imp":2,"text":"The Silver Hounds wake to 3 Kobolds in camp in Redcrag Hills in the middle of the night, and beat them. Isolde landed Pinning Shot on the kobold hard enough to hear from the back. Tamsin's Marching Song kicked in when it counted. Loot: 4 silver each, 3 ore, 2 kobold firepeppers.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"redcrag","fight":"f144","foes":["kobold","kobold","kobold"],"where":"at their camp in Redcrag Hills, in the middle of the night","won":true,"close":false,"shape":"night","reworded":-11},{"id":"e2015","day":57,"season":2,"sday":27,"kind":"meet","imp":2,"text":"The Silver Hounds and The Thunder of Frosthold share a fire in Redcrag Hills. Nobody draws steel, which counts as a good meeting these days.","heroes":["h4","h18","h16","h5","h3","h2","h11"],"parties":["p8","p3"],"loc":"redcrag"},{"id":"e2016","day":57,"season":2,"sday":27,"kind":"talent","imp":1,"text":"Isolde casts a line from every bridge on the route. At the fourth, a pike. Isolde names it. Angler: a ranger's patience, mostly.","heroes":["h18"],"parties":["p8"],"loc":"redcrag","skill":"angler"},{"id":"e2027","day":57,"season":2,"sday":27,"kind":"campfire","imp":1,"text":"Isolde reads the map upside down for an hour. Pickles lets it happen and never brings it up. Mostly.","heroes":["h4","h18"],"parties":["p8"],"loc":"redcrag"},{"id":"e2055","day":59,"season":2,"sday":29,"kind":"fight","imp":2,"text":"It's 3 Kobolds and a Giant Bat against the Silver Hounds in Redcrag Hills, and it isn't close. The last giant bat decides enough is enough, and goes. Isolde's Patient Shot put the kobold down. Pickles landed the hit that turned it, then went straight back to guarding the packs. Loot: 5 silver each, 1 ore, 2 kobold firepeppers.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"redcrag","fight":"f146","foes":["kobold","kobold","kobold"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"foe","reworded":-53,"wx":"heat"},{"id":"e2100","day":60,"season":2,"sday":30,"kind":"ability","imp":2,"text":"Tamsin starts a slow ballad in a rowdy Veldrock tavern and the room goes quiet to listen. Then the encore, then 34 silver, then Isolde carrying the hat home.","heroes":["h16","h18"],"parties":["p8"],"loc":"veldrock","skill":"packs_the_house","sk":"Packs the House","rule":true},{"id":"e2115","day":60,"season":2,"sday":30,"kind":"goal_done","imp":4,"text":"GOAL: The Silver Hounds set out to finish the season as one of the top three parties, and the final table says they made it. XP: Pickles +800 (level 17!), Isolde +800 (level 17!), Tamsin +800 (level 17!).","heroes":[],"parties":["p8"],"xp":{"h4":800,"h18":800,"h16":800}},{"id":"e2117","day":60,"season":2,"sday":30,"kind":"season_end","imp":5,"text":"Season 2 ends. Isolde is Hero of the Season with 293 renown. The Silver Hounds finish as the top party.","heroes":["h18","h4","h16"],"parties":["p8"]},{"id":"e2118","day":60,"season":2,"sday":30,"kind":"top_party","imp":4,"text":"TOP PARTY: The Silver Hounds (Pickles, Isolde and Tamsin) end season 2 as the league's best crew, 425 party renown. Their season: 1 boss, 11 fights won and 5 floors explored.","heroes":["h4","h18","h16"],"parties":["p8"]},{"id":"e2136","day":61,"season":3,"sday":1,"kind":"party_life","imp":1,"text":"Tamsin spends the whole road in the Wheelie pointing out every bump to whoever is driving.","heroes":["h16"],"parties":["p8"],"loc":"ironhaven"},{"id":"e2140","day":61,"season":3,"sday":1,"kind":"boss_race","imp":3,"text":"The Thunder of Frosthold and The Silver Hounds are headed for the same hole in the ground: Frostspire, where Hrimnir, Who Walks Under Snow waits. Somebody is going to be disappointed.","heroes":["h5","h3","h2","h11","h4","h18","h16"],"parties":["p3","p8"],"loc":"frostspire"},{"id":"e2192","day":63,"season":3,"sday":3,"kind":"night","imp":1,"text":"A grey dwarf shares The Silver Hounds' fire in Whitepeak Pass and swears on his beard there's a room in the Sunken Vault nobody has opened. There isn't much beard left.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"whitepeak"},{"id":"e2205","day":63,"season":3,"sday":3,"kind":"campfire","imp":1,"text":"Pickles and Tamsin find a pear tree by the road and eat far more than is wise.","heroes":["h4","h16"],"parties":["p8"],"loc":"whitepeak"},{"id":"e2235","day":64,"season":3,"sday":4,"kind":"meet","imp":1,"text":"The Silver Hounds and The Thunder of Frosthold share a fire in Frostspire. Nobody draws steel, which counts as a good meeting these days.","heroes":["h4","h18","h16","h5","h3","h2","h11"],"parties":["p8","p3"],"loc":"frostspire"},{"id":"e2268","day":65,"season":3,"sday":5,"kind":"delve","imp":1,"text":"The Silver Hounds descend into Frostspire, mostly unexplored (22%).","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"frostspire","wx":"snow"},{"id":"e2269","day":65,"season":3,"sday":5,"kind":"night","imp":1,"text":"Something small and clever gets into The Silver Hounds' camp on floor 2 of Frostspire overnight. Pickles wakes up 10 silver and 1 ration lighter.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"frostspire","wx":"snow"},{"id":"e2275","day":65,"season":3,"sday":5,"kind":"gift","imp":2,"text":"The Kobold Whistle changes hands again: Tamsin to Pickles this time. It has been passed around this crew 2 times now.","heroes":["h16","h4"],"parties":["p8"],"loc":"frostspire","wx":"snow"},{"id":"e2301","day":66,"season":3,"sday":6,"kind":"delve_day","imp":1,"text":"The Silver Hounds work floor 2 of Frostspire at a steady pace: 3 rooms (the buried trunks, the gallery of ice figures, the white chapel).","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"frostspire","pace":"steady","stats":{"rooms":3,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":0,"wild":[]},"wx":"snow"},{"id":"e2313","day":66,"season":3,"sday":6,"kind":"talent","imp":2,"text":"Isolde puts an arrow into a crack in the wall. 'Lever's there.' It is. Chalk it up to Follow My Arrow.","heroes":["h18"],"parties":["p8"],"loc":"frostspire","skill":"follow_my_arrow","wx":"snow"},{"id":"e2328","day":67,"season":3,"sday":7,"kind":"fight","imp":2,"text":"The Silver Hounds run into 3 Frost Wolves and a Yeti in the yeti dens on floor 2 of Frostspire and come out on top. Isolde's Patient Shot took most of the fight out of the yeti in one go. Loot: 15 pelts, 1 frost crystal, 3 yeti steaks.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"frostspire","fight":"f171","foes":["yeti","frost_wolf","frost_wolf"],"where":"in the yeti dens on floor 2 of Frostspire","won":true,"close":false,"shape":"plain","reworded":-22,"wx":"snow"},{"id":"e2329","day":67,"season":3,"sday":7,"kind":"delve_day","imp":1,"text":"The Silver Hounds work floor 2 of Frostspire at a push pace: 4 rooms (the steaming vent, the yeti dens, the yeti's nest of shinies and 1 more).","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"frostspire","pace":"push","stats":{"rooms":4,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":1,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"snow"},{"id":"e2364","day":68,"season":3,"sday":8,"kind":"delve_day","imp":1,"text":"The Silver Hounds work floor 2 of Frostspire at a steady pace: 1 room (the draught hole).","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"frostspire","pace":"steady","stats":{"rooms":1,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"snow"},{"id":"e2365","day":68,"season":3,"sday":8,"kind":"delve_done","imp":3,"text":"The Silver Hounds come out into the light after 4 days with the dark still in every seam. They reached floor 2, mapped 15% of it, found the buried trunks and the yeti's nest of shinies, took 6 rooms off the map's blank side, split 38 silver on the way up and turned back because the way on beat them twice, and they mean to come back with more. Add up every party's sketches and Frostspire comes out partly explored (35%).","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"frostspire","days":4,"bottom":false,"rooms":["the buried trunks","the yeti's nest of shinies"],"gold":38,"turn":"blocked","wx":"snow"},{"id":"e2378","day":68,"season":3,"sday":8,"kind":"talent","imp":1,"text":"Pickles frosts the meat bag every evening. The crew eats week-old venison that tastes like Tuesday's. Every druid learns Icehouse sooner or later. Not every druid learns it like that.","heroes":["h4"],"parties":["p8"],"loc":"frostspire","skill":"icehouse","wx":"snow"},{"id":"e2389","day":69,"season":3,"sday":9,"kind":"night_game","imp":2,"text":"The crew braces for a fight on the road to Whitepeak Pass, but the yeti only clears a flat stone and says: a round of Snow Stones, and who is first? Pickles wins, and the yeti takes it well, mostly, and surrenders Yeti Fur Charm before anyone changes their mind. Tamsin tells Pickles the next ambush can be fought, thanks. Pickles says that is fair.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"whitepeak","night":"n133","monster_game":"yeti","wx":"snow"},{"id":"e2399","day":69,"season":3,"sday":9,"kind":"journey","imp":2,"text":"The Thunder of Frosthold and The Silver Hounds walk to Whitepeak Pass together. Someone brings up old scars. Someone always does.","heroes":["h5","h3","h2","h11","h4","h18","h16"],"parties":["p3","p8"]},{"id":"e2402","day":69,"season":3,"sday":9,"kind":"talent","imp":1,"text":"Isolde fords a river where the map says you can't. The map is corrected in pencil.","heroes":["h18"],"parties":["p8"],"loc":"whitepeak","skill":"trailblazer","wx":"snow"},{"id":"e2411","day":69,"season":3,"sday":9,"kind":"campfire","imp":1,"text":"Tamsin admits to being afraid of being alone. Pickles doesn't laugh. Pickles just nods and takes the watch nearest it.","heroes":["h4","h16"],"parties":["p8"],"loc":"whitepeak","wx":"snow"},{"id":"e2438","day":70,"season":3,"sday":10,"kind":"talent","imp":2,"text":"Isolde makes a bunch of flowers bloom for a Frosthold child. The child's grandmother pays in tart. The words of Cantrips, half under her breath.","heroes":["h18"],"parties":["p8"],"loc":"frosthold","skill":"cantrips","wx":"snow"},{"id":"e2440","day":70,"season":3,"sday":10,"kind":"argument","imp":2,"text":"It starts with who ate the last of the cheese. It ends with Pickles and Tamsin sleeping on opposite sides of the fire.","heroes":["h4","h16"],"parties":["p8"]},{"id":"e2457","day":71,"season":3,"sday":11,"kind":"campfire","imp":1,"text":"Pickles saves Tamsin the good spot by the fire. Again.","heroes":["h4","h16"],"parties":["p8"],"loc":"veldrock","wx":"snow"},{"id":"e2466","day":71,"season":3,"sday":11,"kind":"goal","imp":2,"text":"The Silver Hounds' plan for the season, as told to the barkeep: to find a relic of the old world.","heroes":["h4","h18","h16"],"parties":["p8"]},{"id":"e2476","day":72,"season":3,"sday":12,"kind":"party_life","imp":1,"text":"Tamsin has started sitting on a folded cloak in the Wheelie, as a statement.","heroes":["h16"],"parties":["p8"],"loc":"veldrock","wx":"snow"},{"id":"e2528","day":73,"season":3,"sday":13,"kind":"talent","imp":2,"text":"A Saltmarrow street crowd learns the chorus to Tamsin's newest song in one go. That's Packs the House for you.","heroes":["h16"],"parties":["p8"],"loc":"saltmarrow","skill":"packs_the_house"},{"id":"e2586","day":75,"season":3,"sday":15,"kind":"night","imp":1,"text":"Tamsin's ghost story in the Sunken Vault goes on too long and never really ends. Isolde lies awake waiting for the ending.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"sunken_vault"},{"id":"e2596","day":75,"season":3,"sday":15,"kind":"meet","imp":1,"text":"The Green Arrows and The Silver Hounds share a fire in the Sunken Vault. Nobody draws steel, which counts as a good meeting these days.","heroes":["h17","h13","h14","h4","h18","h16"],"parties":["p5","p8"],"loc":"sunken_vault"},{"id":"e2617","day":76,"season":3,"sday":16,"kind":"delve","imp":1,"text":"The Silver Hounds descend into the Sunken Vault, partly explored (42%).","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"sunken_vault"},{"id":"e2618","day":76,"season":3,"sday":16,"kind":"night","imp":3,"text":"Pickles tells a ghost story by the fire on floor 3 of the Sunken Vault. Tamsin laughs at it, then moves their bedroll closer to the others.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"sunken_vault"},{"id":"e2657","day":77,"season":3,"sday":17,"kind":"wild_room","imp":3,"text":"The Sunken Vault siren has a regular card night now. Thursdays. Pickles brings the snacks.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"sunken_vault","room":"wild_tide_cards"},{"id":"e2659","day":77,"season":3,"sday":17,"kind":"fight","imp":1,"text":"Tamsin hits hardest as the Silver Hounds beat a Sea Serpent in a drowned staircase with a brass handrail on floor 3 of the Sunken Vault. Tamsin's last Headshot settled it. Loot: 1 drake scale, 11 fangs & claws, 4 serpent fillets.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"sunken_vault","fight":"f199","foes":["sea_serpent"],"where":"in a drowned staircase with a brass handrail on floor 3 of the Sunken Vault","won":true,"close":false,"shape":"hero","reworded":-23},{"id":"e2660","day":77,"season":3,"sday":17,"kind":"delve_day","imp":1,"text":"The Silver Hounds work floor 3 of the Sunken Vault at a steady pace: 3 rooms (the siren's card table, a drowned staircase with a brass handrail, the silted atrium).","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":3,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":["wild_tide_cards"]}},{"id":"e2699","day":78,"season":3,"sday":18,"kind":"delve_day","imp":1,"text":"The Silver Hounds work floor 3 of the Sunken Vault at a push pace: 1 room (the cracked foundation).","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"sunken_vault","pace":"push","stats":{"rooms":1,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2716","day":79,"season":3,"sday":19,"kind":"artifact","imp":5,"text":"Deep in the Sunken Vault, Isolde finds something with a name: the Patient Clock. It has clearly been waiting for someone.","heroes":["h18"],"parties":["p8"],"loc":"sunken_vault"},{"id":"e2717","day":79,"season":3,"sday":19,"kind":"delve_day","imp":1,"text":"The Silver Hounds work floor 3 of the Sunken Vault at a push pace: 1 room (the cracked foundation).","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"sunken_vault","pace":"push","stats":{"rooms":1,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2718","day":79,"season":3,"sday":19,"kind":"delve_done","imp":1,"text":"The Silver Hounds climb the last ladder after 4 days, and the sitting down happens at the top of it. They made it to floor 3, took 3 rooms off the map's blank side, found the siren's card table, came away with 27 silver between them and turned back because the way on beat them twice, and they mean to come back with more.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"sunken_vault","days":4,"bottom":false,"rooms":["the siren's card table"],"gold":27,"turn":"blocked"},{"id":"e2728","day":79,"season":3,"sday":19,"kind":"boss_race","imp":2,"text":"The Silver Hounds drop out of the race for The Kraken of the Vault. That leaves The Sigil of Thornwall in it.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"sunken_vault"},{"id":"e2737","day":79,"season":3,"sday":19,"kind":"talent","imp":2,"text":"Pickles sleeps under an oak and wakes with acorns in her pockets and a much better mood. Chalk it up to Heart of the Wild.","heroes":["h4"],"parties":["p8"],"loc":"sunken_vault","skill":"heart_of_the_wild"},{"id":"e2763","day":80,"season":3,"sday":20,"kind":"talent","imp":1,"text":"Tamsin tries out a new verse on the party. Pickles suggests a rhyme. It's in the song now. Somebody asks how. 'Packs the House,' says Tamsin.","heroes":["h16","h4"],"parties":["p8"],"loc":"saltcliffs","skill":"packs_the_house"},{"id":"e2773","day":80,"season":3,"sday":20,"kind":"campfire","imp":2,"text":"Pickles and Tamsin wait out a hailstorm under one cart and play twenty questions with no winner.","heroes":["h4","h16"],"parties":["p8"],"loc":"saltcliffs"},{"id":"e2805","day":81,"season":3,"sday":21,"kind":"campfire","imp":1,"text":"Pickles wakes up to find Tamsin has already made the tea. Exactly how Pickles likes it.","heroes":["h4","h16"],"parties":["p8"],"loc":"saltmarrow"},{"id":"e2810","day":81,"season":3,"sday":21,"kind":"ledger","imp":2,"text":"MARKET WEEK: 12 hauls sold across the realm, 714 silver all told. Biggest haul: Bramble, 174 silver in Saltmarrow. Back up from the deep: Jade Wall (2 days in the Collapsed Mine), Brix (4 days in the Wolf Den), The Silver Hounds (4 days in the Sunken Vault), The Sigil of Thornwall (3 days in the Sunken Vault).","heroes":["h13","h10","h1","h4"],"parties":["p10","p8","p9"]},{"id":"e2817","day":82,"season":3,"sday":22,"kind":"map_bought","imp":2,"text":"The Silver Hounds buy a map of the Sunken Vault in Saltmarrow for 71 silver, drawn by Ottoline. The place is partly explored (52%).","heroes":["h4","h18","h16","h14"],"parties":["p8"],"loc":"saltmarrow"},{"id":"e2818","day":82,"season":3,"sday":22,"kind":"talent","imp":2,"text":"Isolde lets Pickles pick the target: a knot on a far pine. Dead centre. Pickles picks a harder one. That's Follow My Arrow for you.","heroes":["h18","h4"],"parties":["p8"],"loc":"saltcliffs","skill":"follow_my_arrow"},{"id":"e2892","day":84,"season":3,"sday":24,"kind":"delve","imp":1,"text":"The Silver Hounds descend into the Sunken Vault, partly explored (52%), map in hand.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"sunken_vault"},{"id":"e2902","day":84,"season":3,"sday":24,"kind":"boss_race","imp":3,"text":"The Kraken of the Vault has visitors coming. The Silver Hounds and The Sigil of Thornwall are both on the way to the Sunken Vault, and nobody is waiting for the others.","heroes":["h4","h18","h16","h20","h8"],"parties":["p8","p9"],"loc":"sunken_vault"},{"id":"e2915","day":85,"season":3,"sday":25,"kind":"delve_day","imp":1,"text":"The Silver Hounds work floor 3 of the Sunken Vault at a push pace: 1 room (the cracked foundation).","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"sunken_vault","pace":"push","stats":{"rooms":1,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2936","day":85,"season":3,"sday":25,"kind":"talent","imp":1,"text":"Isolde fletches arrows by the fire, matching each feather to the last. The quiver is full by bedtime.","heroes":["h18"],"parties":["p8"],"loc":"sunken_vault","skill":"fletcher"},{"id":"e2953","day":86,"season":3,"sday":26,"kind":"delve_day","imp":1,"text":"The Silver Hounds work floor 3 of the Sunken Vault at a steady pace: 1 room (the cracked foundation).","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":1,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"storm"},{"id":"e2954","day":86,"season":3,"sday":26,"kind":"delve_done","imp":1,"text":"The Silver Hounds come up for air after 3 days, pockets heavier and boots wetter. They got down to floor 3 and turned back because the way on beat them twice, and they mean to come back with more.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"sunken_vault","days":3,"bottom":false,"rooms":[],"gold":0,"turn":"blocked","wx":"storm"},{"id":"e2964","day":86,"season":3,"sday":26,"kind":"boss_race","imp":2,"text":"The Silver Hounds give up on The Kraken of the Vault for now, and the race to the Sunken Vault belongs to The Sigil of Thornwall.","heroes":["h4","h18","h16"],"parties":["p8"],"loc":"sunken_vault","wx":"storm"},{"id":"e3018","day":88,"season":3,"sday":28,"kind":"ability","imp":2,"text":"Tamsin plays a wet Tuesday at a Saltmarrow tavern to six people and a dog. By the last song there are sixty, and the dog is howling along. 48 silver in the hat.","heroes":["h16"],"parties":["p8"],"loc":"saltmarrow","skill":"packs_the_house","sk":"Packs the House","rule":true,"wx":"storm"},{"id":"e3027","day":88,"season":3,"sday":28,"kind":"ledger","imp":2,"text":"Counters and coin this week: 11 sales, 1,109 silver changing hands. Biggest haul: Fenwick, 264 silver in Carrbridge. Back up from the deep: Brix (1 day in Goblin Camp), Jade Wall (2 days in the Collapsed Mine), The Silver Hounds (3 days in the Sunken Vault), The Tidal Ledger (3 days in the Ashveil Crypts), The Sigil of Thornwall (3 days in the Sunken Vault).","heroes":["h17","h1","h10","h4"],"parties":["p10","p8","p7"]},{"id":"e3049","day":89,"season":3,"sday":29,"kind":"party_life","imp":1,"text":"Tamsin spends the whole road in the Wheelie pointing out every bump to whoever is driving.","heroes":["h16"],"parties":["p8"],"loc":"saltmarrow"},{"id":"e3094","day":90,"season":3,"sday":30,"kind":"goal_missed","imp":3,"text":"Season's end, and The Silver Hounds came up short: find a relic of the old world (still looking).","heroes":["h4","h18","h16"],"parties":["p8"]},{"id":"e3103","day":90,"season":3,"sday":30,"kind":"vow_kept","imp":4,"text":"VOWS KEPT TO THE END OF THE AGE: The Scarlet Thorns, never to retreat (sworn in season 2); The Thunder of Frosthold, to share every coin (sworn in season 2); The Green Arrows, to die rich (sworn in season 2); The Tidal Ledger, never to retreat (sworn in season 2); The Silver Hounds, never to pay a toll (sworn in season 2); Jade Wall, to keep the peace: never draw first on another hero (sworn in season 1); Brix, never to pay a toll (sworn in season 2); Rook, to keep the peace: never draw first on another hero (sworn in season 2); and 1 more. Every one of them held.","heroes":["h1","h15","h17"],"parties":["p1","p10","p3","p5","p7","p8"]}],"roles":{"h16":"Leader · Face","h18":"Blade","h4":"Tracker"},"quest":{"what":"Delve","where":"The Sunken Vault","why":"chasing a rumour: about 54 silver a day each, risk slight; the season goal: to find a relic of the old world","floor":0,"floors":4},"tactics":{"front":[],"back":["h4","h18","h16"],"plan":"Pickles casts from behind; Isolde and Tamsin pick off whatever gets close; Pickles keeps everyone standing.","traits":{"boldness":0.12,"risk":0.24,"greed":-0.25,"sociability":-0.19,"honor":0.18,"curiosity":0.28,"temper":0.02,"loyalty":0.14},"mix":"1 caster, 1 bow, 1 talker","notes":["Nobody wants the front row. Whoever's nearest takes the hits."],"style":["balanced"],"skills":[{"label":"Damage","skills":[{"hero":"h18","id":"pinning_shot","name":"Pinning Shot","desc":"Nails a sleeve to a tree.","tags":["crit","nature"],"rank":1,"uses":24},{"hero":"h16","id":"caltrops","name":"Caltrops","desc":"A handful of spikes, scattered where feet go.","tags":["craft","stealth"],"rank":1,"uses":12},{"hero":"h4","id":"thorn_whip","name":"Thorn Whip","desc":"A vine with ideas.","tags":["nature"],"rank":2,"uses":10},{"hero":"h16","id":"pounce","name":"Pounce","desc":"Clears the front rank in one bound.","tags":["beast"],"rank":1,"uses":7},{"hero":"h16","id":"headshot","name":"Headshot","desc":"Between the eyes.","tags":["crit"],"rank":1,"uses":6},{"hero":"h4","id":"natures_wrath","name":"Nature's Wrath","desc":"The forest fights back.","tags":["nature"],"rank":1,"uses":2},{"hero":"h18","id":"hunters_mark","name":"Hunter's Mark","desc":"Marks a target for the whole party.","tags":["crit","beast"],"rank":1,"uses":2},{"hero":"h4","id":"rot_root","name":"Rot Root","desc":"A root that's gone off. It wants company.","tags":["death","nature"],"rank":1,"uses":1}]},{"label":"Healing","skills":[{"hero":"h4","id":"rejuvenate","name":"Rejuvenate","desc":"Green light washes over the party.","tags":["nature","heal"],"rank":2,"uses":4}]},{"label":"Defence","skills":[{"hero":"h4","id":"ice_wall","name":"Ice Wall","desc":"Slams a wall of ice down in front of the party.","tags":["ice","guard"],"rank":2,"uses":15},{"hero":"h16","id":"rousing_ballad","name":"Rousing Ballad","desc":"Four verses about how this all ends well.","tags":["music"],"rank":1,"uses":11},{"hero":"h4","id":"barkskin","name":"Barkskin","desc":"Skin goes knotted and brown. It's fine. It's fine.","tags":["nature","guard"],"rank":1,"uses":3},{"hero":"h16","id":"berserk","name":"Berserk","desc":"The eyes go red. The plan goes out.","tags":["rage"],"rank":1,"uses":0}]},{"label":"Tricks","skills":[{"hero":"h18","id":"marching_song","name":"Marching Song","desc":"Everybody steps off on the same foot.","tags":["music","travel"],"rank":1,"uses":27},{"hero":"h16","id":"marching_song","name":"Marching Song","desc":"Everybody steps off on the same foot.","tags":["music","travel"],"rank":3,"uses":25},{"hero":"h18","id":"patient_shot","name":"Patient Shot","desc":"Has had the shot lined up since breakfast.","tags":["crit"],"rank":2,"uses":19},{"hero":"h18","id":"follow_my_arrow","name":"Follow My Arrow","desc":"Shows you the gap in the armour. With an arrow. Then you hit it too.","tags":[],"rank":1,"uses":11},{"hero":"h4","id":"cold_snap","name":"Cold Snap","desc":"The temperature drops ten degrees, on purpose.","tags":["ice"],"rank":1,"uses":7},{"hero":"h4","id":"heart_of_the_wild","name":"Heart of the Wild","desc":"More forest than person. Very sturdy forest.","tags":[],"rank":1,"uses":1},{"hero":"h4","id":"spore_cloud","name":"Spore Cloud","desc":"A puff of something nobody should breathe.","tags":["nature","death"],"rank":1,"uses":0},{"hero":"h4","id":"plague","name":"Plague","desc":"Everyone feels a bit off. Then very off.","tags":["death","nature"],"rank":1,"uses":0}]},{"label":"Always on","skills":[{"hero":"h18","id":"lucky","name":"Lucky","desc":"Things just work out.","tags":["crit"],"rank":2,"uses":0},{"hero":"h18","id":"precision","name":"Precision","desc":"Finds the gap every time.","tags":["crit"],"rank":1,"uses":0}]},{"label":"On the road","skills":[{"hero":"h4","id":"tavern_brawler","name":"Tavern Brawler","desc":"Ends fights. Occasionally starts them.","tags":["rage"],"rank":1,"uses":0},{"hero":"h4","id":"icehouse","name":"Icehouse","desc":"Keeps the rations fresh for weeks.","tags":["ice"],"rank":2,"uses":0},{"hero":"h4","id":"herbalism","name":"Herbalism","desc":"Knows every useful leaf.","tags":["nature","heal"],"rank":1,"uses":0},{"hero":"h4","id":"green_thumb","name":"Green Thumb","desc":"Grows herbs on the windowsill. The apothecary buys the windowsill.","tags":["nature"],"rank":1,"uses":0},{"hero":"h4","id":"forager","name":"Forager","desc":"Finds dinner and herbs on any trail.","tags":["nature"],"rank":1,"uses":0},{"hero":"h18","id":"local_history","name":"Local History","desc":"Knows who built the bridge, and who fell off it.","tags":["lore","arcane"],"rank":1,"uses":0},{"hero":"h18","id":"cobbler","name":"Cobbler","desc":"New soles for old boots, old roads for new soles.","tags":["craft","travel"],"rank":1,"uses":0},{"hero":"h18","id":"fletcher","name":"Fletcher","desc":"Every arrow straight, every feather matched.","tags":["craft","crit"],"rank":1,"uses":0},{"hero":"h18","id":"farrier","name":"Farrier","desc":"Shoes horses, mends wheels, and charges the crew nothing.","tags":["ride","craft"],"rank":2,"uses":0},{"hero":"h18","id":"trailblazer","name":"Trailblazer","desc":"Cuts a day off long roads.","tags":["travel"],"rank":1,"uses":0},{"hero":"h18","id":"cantrips","name":"Cantrips","desc":"Small magic. Big crowds.","tags":["arcane","lore"],"rank":1,"uses":0},{"hero":"h18","id":"angler","name":"Angler","desc":"Has a line in the water before the tent is up.","tags":[],"rank":1,"uses":0},{"hero":"h18","id":"mushroom_hunter","name":"Mushroom Hunter","desc":"Knows which ones are dinner and which ones are a funeral.","tags":[],"rank":1,"uses":0},{"hero":"h16","id":"drinking_songs","name":"Drinking Songs","desc":"Knows every verse. Especially the forbidden ones.","tags":["music","rage"],"rank":1,"uses":0},{"hero":"h16","id":"busker","name":"Busker","desc":"Hat on the ground, song in the air.","tags":["music","travel"],"rank":2,"uses":0},{"hero":"h16","id":"supply_master","name":"Supply Master","desc":"Gets supplies at cost.","tags":["trade"],"rank":1,"uses":0},{"hero":"h16","id":"spice_box","name":"Spice Box","desc":"Carries a tin of spices the size of a hymnal, and uses it.","tags":[],"rank":1,"uses":0},{"hero":"h16","id":"snowcraft","name":"Snowcraft","desc":"Knows snow: which holds, which slides, which bites.","tags":["ice","travel"],"rank":1,"uses":0},{"hero":"h16","id":"songwriter","name":"Songwriter","desc":"Every fight becomes a verse, eventually.","tags":["music"],"rank":2,"uses":0},{"hero":"h16","id":"name_in_lights","name":"Name in Lights","desc":"People join the crew just to be in the next verse.","tags":["music"],"rank":1,"uses":0}]}],"share":[{"hero":"h4","dmg":95,"healed":0,"taken":24,"kills":1,"row":"back"},{"hero":"h18","dmg":512,"healed":0,"taken":66,"kills":2,"row":"back"},{"hero":"h16","dmg":555,"healed":0,"taken":24,"kills":2,"row":"back"}],"ground":{"name":"The Ashveil Crypts","fights":5}},"trophies":[{"boss":"The Silk Matriarch","monster":"spider_queen","place":"The Collapsed Mine","day":15,"season":1,"fight":"f46"},{"boss":"The Mimic King","monster":"mimic_king","place":"Cragtooth Warren","day":24,"season":1,"fight":"f71"},{"boss":"Mother Thornmere","monster":"hag_mother","place":"Thornmere Ruins","day":53,"season":2,"fight":"f131"}]};